a, b = 11, 20
f0 = set()
limit = (a - 1) * (b - 1)
for x in range(limit // a + 1):
    for y in range(limit // b + 1):
        val = a * x + b * y
        if val <= limit:
            f0.add(val)

X = [n for n in range(limit + 1) if n not in f0]
adj = {n: [] for n in X}
edges = 0
for n in X:
    for m in X:
        if m > n and (m - n) in f0:
            adj[n].append(m)
            edges += 1
print(f"Number of edges: {edges}")

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

print(fib(30))
